// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {TimelockController} from "../src/TimelockController.sol";

contract InvMutTest is Test {
    TimelockController c;
    bytes32 constant TIMELOCK_ADMIN_ROLE = keccak256("TIMELOCK_ADMIN_ROLE");

    function setUp() public { c = new TimelockController(0, new address[](0), new address[](0)); }

    function testFuzz_property(bytes32 role) public {
        // Exclude the roles where the stored admin role legitimately equals the role itself:
        // the zero role (DEFAULT_ADMIN_ROLE has admin 0x00) and TIMELOCK_ADMIN_ROLE (self-administered).
        vm.assume(role != bytes32(0));
        vm.assume(role != TIMELOCK_ADMIN_ROLE);
        // Rule: for every other role, the stored admin role is never equal to the role itself.
        assertTrue(c.getRoleAdmin(role) != role);
    }
}
